function roundRect(c,x,y,w,h,r){c.beginPath();c.moveTo(x+r,y);c.arcTo(x+w,y,x+w,y+h,r);c.arcTo(x+w,y+h,x,y+h,r);c.arcTo(x,y+h,x,y,r);c.arcTo(x,y,x+w,y,r);c.closePath();}
function togglePause(){if(!state.running&&!state.paused)return;state.paused=!state.paused;document.getElementById('pause-overlay').classList.toggle('hidden',!state.paused);document.getElementById('pause-button').textContent=state.paused?'▶ REANUDAR':'Ⅱ PAUSA';if(!state.paused){state.lastFrame=0;}}
function updateSurvivalHUD(){
 const hud=document.getElementById('survival-hud');if(!hud)return;
 const isSurvival=state.preparationMode==='survival';
 document.body.classList.toggle('survival-mode',isSurvival);
 const visible=isSurvival&&(survivalCampaign.active||survivalCampaign.outcome);
 hud.classList.toggle('hidden',!visible);if(!visible)return;
 const stage=document.getElementById('survival-stage-label'),lives=document.getElementById('survival-lives'),enemy=document.getElementById('survival-enemy-label'),rule=document.getElementById('survival-enemy-rule'),fill=document.getElementById('survival-progress-fill'),track=fill?.parentElement,progressText=document.getElementById('survival-progress-text');
 if(stage)stage.textContent=survivalCampaign.outcome==='victory'?'SUPERVIVENCIA COMPLETADA · VICTORIA':survivalCampaign.outcome==='defeat'?'FIN DE LA SUPERVIVENCIA':survivalCampaign.boss?'JEFE FINAL · BATALLA DEFINITIVA':`SUPERVIVENCIA · RIVAL ${survivalCampaign.encounter}/15`;
 if(lives){lives.textContent='♥ '.repeat(survivalCampaign.lives)+'♡ '.repeat(3-survivalCampaign.lives);lives.setAttribute('aria-label',`${survivalCampaign.lives} de 3 vidas restantes`);}
 if(enemy)enemy.textContent=GODS[state.selected.p2]?.name?.toUpperCase()||'RIVAL ALEATORIO';
 if(rule)rule.textContent=`${state.winScore||7} PUNTOS PARA GANAR`;
 const completed=survivalCampaign.clearedEncounters||0;const progress=survivalCampaign.outcome==='victory'?16:completed;
 if(fill)fill.style.width=`${Math.min(100,progress/16*100)}%`;
 if(track)track.setAttribute('aria-valuenow',String(progress));
 if(progressText)progressText.textContent=survivalCampaign.outcome==='victory'?'DESAFÍO COMPLETADO · 16/16':survivalCampaign.boss?`15/15 RIVALES · JEFE FINAL`:`${completed}/15 RIVALES SUPERADOS`;
}
function finishMatch(e){
 clearArenaEventState();clearArenaDirector();
 const winner=e.detail.winner,opponentIdAtFinish=state.selected.p2,protagonistIdAtFinish=state.selected.p1;
 const side=winner==='p1'?'p1':'p2',god=GODS[state.selected[side]],mutationLoss=state.mutationMode==='mutation'&&e.detail.reason==='corruption',loserSide=e.detail.loser||(winner==='p1'?'p2':'p1'),loser=GODS[state.selected[loserSide]];
 const title=document.getElementById('result-title'),emblem=document.getElementById('result-emblem'),description=document.getElementById('result-description'),rematch=document.getElementById('rematch-button');
 if(state.preparationMode==='survival'&&(survivalCampaign.active||survivalCampaign.outcome)){
  const playerWon=winner==='p1',defeatedOpponent=GODS[opponentIdAtFinish],protagonist=GODS[protagonistIdAtFinish];
  const result=completeSurvivalMatch(winner);updateSurvivalHUD();
  title.style.color=result?.type==='victory'?'#f4d17a':result?.type==='defeat'?'#ff7187':playerWon?(protagonist?.color||god.color):(defeatedOpponent?.color||god.color);
  emblem.textContent=result?.type==='victory'?'♛':result?.type==='defeat'?'☠':result?.type==='boss-unlocked'?'♜':playerWon?(protagonist?.symbol||god.symbol):(defeatedOpponent?.symbol||god.symbol);
  if(result?.type==='victory'){
   title.textContent='SUPERVIVENCIA COMPLETADA';description.textContent=`${protagonist.name} derrotó al jefe final ${defeatedOpponent.name} y completó el desafío. Rivales superados: 15/15. Victorias: ${survivalCampaign.wins}; combates perdidos: ${survivalCampaign.losses}. Vidas restantes: ${result.lives}.`;rematch.textContent='NUEVA PARTIDA ↻';
  }else if(result?.type==='defeat'){
   title.textContent='FIN DE LA SUPERVIVENCIA';description.textContent=`${protagonist.name} se quedó sin vidas. ${result.boss?`El jefe final ${defeatedOpponent.name} resistió.`:`Tu último rival fue ${defeatedOpponent.name}; llegaste al rival ${result.encounter} de 15 y superaste ${result.clearedEncounters}/15.`} Victorias: ${survivalCampaign.wins}; combates perdidos: ${survivalCampaign.losses}.`;rematch.textContent='NUEVA PARTIDA ↻';
  }else if(result?.type==='boss-unlocked'){
   title.textContent='EL JEFE FINAL TE ESPERA';description.textContent=`Superaste los 15 rivales y derrotaste a ${defeatedOpponent.name}. ${GODS[state.selected.p2].name} aparece como jefe final reforzado. Vidas restantes: ${result.lives}.`;rematch.textContent='ENFRENTAR JEFE FINAL ↗';
  }else if(result?.type==='retry-boss'){
   title.textContent='EL JEFE SIGUE EN PIE';description.textContent=`${defeatedOpponent.name} te derrotó y perdiste una vida. El jefe no cambia: tendrás que vencerlo para completar el desafío. Vidas restantes: ${result.lives}.`;rematch.textContent='REINTENTAR JEFE ↻';
  }else if(result?.type==='retry-encounter'){
   title.textContent='EL RIVAL TE DETUVO';description.textContent=`${defeatedOpponent.name} ganó este combate. Perdiste una vida, pero el rival ${result.encounter}/15 sigue pendiente. Vencelo para avanzar. Vidas restantes: ${result.lives}.`;rematch.textContent='REINTENTAR RIVAL ↻';
  }else{
   title.textContent='RIVAL SUPERADO';description.textContent=`${protagonist.name} venció a ${defeatedOpponent.name}. Rival ${result?.clearedEncounters||survivalCampaign.clearedEncounters}/15 superado. Próximo rival: ${GODS[state.selected.p2].name}. Vidas restantes: ${result?.lives}.`;rematch.textContent='SIGUIENTE RIVAL ↗';
  }
  document.getElementById('result-p1').textContent=state.scores.p1;document.getElementById('result-p2').textContent=state.scores.p2;showScreen('result');return;
 }
 title.textContent=mutationLoss?`${god.name.toUpperCase()} SOBREVIVE`:`${god.name.toUpperCase()} TRIUNFA`;title.style.color=mutationLoss?'#a7ff7c':god.color;emblem.textContent=mutationLoss?'✚':god.symbol;description.textContent=mutationLoss?`${loser.name} alcanzó el 100% de corrupción y sucumbió a la Cancha Mutante. ${god.name} sobrevivió a la mutación.`:`${god.skill.name} inclinó el destino de la arena. ${god.name} (${characterKindLabel(god).toLowerCase()}) se queda con la victoria.`;document.getElementById('result-p1').textContent=state.scores.p1;document.getElementById('result-p2').textContent=state.scores.p2;rematch.textContent='REVANCHA ↻';showScreen('result');
}
